css:
body :where([data-bz-node="cp"]) .bz-block{padding:0}
body :where([data-bz-node="cp"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="cp"]>.bz-container{padding-inline:0}

body [data-bz-node="cp"]{background:var(--paper);padding:90px 0}
body [data-bz-node="cp"]>.bz-container{max-width:var(--container)}
body [data-bz-node="cp-h"] h2{font:700 36px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="cp-head"]{margin-bottom:34px}
body [data-bz-node="cp-grid2"]{margin-top:24px}
body [data-bz-node="cp-grid"]{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,250px),1fr));gap:24px;align-items:stretch}
body [data-bz-node="cp-grid2"]{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,250px),1fr));gap:24px;align-items:stretch}

body [data-bz-node^="cp-card-"]{grid-column:auto;display:flex;flex-direction:column;background:#fff;border:1px solid #d4d4d2;padding:32px 30px 34px;box-sizing:border-box}
body [data-bz-node^="cp-title-"] h3{font:700 22px/1.15 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0 0 18px}
body [data-bz-node^="cp-para-"]{display:block;margin-bottom:14px}
body [data-bz-node^="cp-para-"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0;margin:0}
body [data-bz-node^="cp-cta-"]{margin-top:auto;padding-top:10px}
body [data-bz-node^="cp-cta-"] .bz-btns{margin:0}
body [data-bz-node^="cp-cta-"] .bz-btn{display:inline-flex;align-items:center;justify-content:center;height:44px;padding:0 24px;border:0;border-radius:2px;background:var(--accent);color:#fff;font:700 11px/1 var(--font-body);letter-spacing:.18em;text-transform:uppercase;text-decoration:none}
body [data-bz-node^="cp-cta-"] .bz-btn:hover{background:var(--accent-dark)}

body [data-bz-node^="cq-card-"]{grid-column:auto;display:flex;flex-direction:column;background:#fff;border:1px solid #d4d4d2;padding:32px 30px 34px;box-sizing:border-box}
body [data-bz-node^="cq-title-"] h3{font:700 22px/1.15 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0 0 18px}
body [data-bz-node^="cq-para-"]{display:block;margin-bottom:14px}
body [data-bz-node^="cq-para-"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0;margin:0}
body [data-bz-node^="cq-cta-"]{margin-top:auto;padding-top:10px}
body [data-bz-node^="cq-cta-"] .bz-btns{margin:0}
body [data-bz-node^="cq-cta-"] .bz-btn{display:inline-flex;align-items:center;justify-content:center;height:44px;padding:0 24px;border:0;border-radius:2px;background:var(--accent);color:#fff;font:700 11px/1 var(--font-body);letter-spacing:.18em;text-transform:uppercase;text-decoration:none}
body [data-bz-node^="cq-cta-"] .bz-btn:hover{background:var(--accent-dark)}

body :is([data-bz-node="cp-grid"],[data-bz-node="cp-grid2"])>.bz-col{grid-column:auto}
@media (max-width:1100px){body [data-bz-node="cp"]{padding:64px 24px}body [data-bz-node="cp-h"] h2{font-size:30px}}
@media (max-width:640px){body [data-bz-node="cp"]{padding:48px 20px}body [data-bz-node="cp-h"] h2{font-size:26px}body :is([data-bz-node^="cp-card-"],[data-bz-node^="cq-card-"]){padding:24px 20px 26px}body :is([data-bz-node^="cp-title-"],[data-bz-node^="cq-title-"]) h3{font-size:19px}}
